import { z } from "zod/v4";
import type { TokenStore } from "./browser-storage";

// The Better Auth fetch resolves to a `{ data }` envelope; the exchange endpoint's data carries
// the app's minted bearer token.
const exchangeResponseSchema = z.object({ data: z.object({ token: z.string() }) });

/** The slice of the Better Auth client's fetch the managed flow needs. */
export type AuthFetch = (
  path: string,
  options?: { method: "GET" | "POST"; body?: Record<string, string> },
) => Promise<unknown>;

export interface ExchangeInput {
  /** The broker-minted identity JWT from the callback fragment. */
  token: string;
  /** PKCE verifier for flows that sent a `code_challenge` to `/start` (native/desktop legs). */
  codeVerifier?: string;
}

/**
 * Hands the broker JWT to the app's own server through the Better Auth client's fetch — so it
 * targets the client's `baseURL`/`basePath` on every platform — and returns the app's minted
 * bearer session token: the token platform clients store and send, never the broker JWT.
 */
export const exchangeToken = async ($fetch: AuthFetch, input: ExchangeInput) => {
  const body: Record<string, string> = { token: input.token };
  if (input.codeVerifier) body.codeVerifier = input.codeVerifier;
  const response = await $fetch("/managed/exchange", { method: "POST", body });
  const result = exchangeResponseSchema.safeParse(response);
  if (!result.success) throw new Error("Managed auth exchange failed");
  return result.data.data.token;
};

interface CompleteExchangeContext {
  $fetch: AuthFetch;
  storage: TokenStore;
}

/** Exchange-and-store with the shared error contract — the final leg of every platform's flow. */
export const completeExchange = async (
  { $fetch, storage }: CompleteExchangeContext,
  input: ExchangeInput,
) => {
  try {
    storage.setToken(await exchangeToken($fetch, input));
    return { data: { success: true }, error: null };
  } catch {
    return {
      data: null,
      error: { code: "EXCHANGE_FAILED", message: "Managed auth exchange failed" },
    };
  }
};
